#!/usr/bin/env bash
# Task 1: compile and run Hello, then compare the output.
# Do not edit this file.
set -u
cd "$(dirname "$0")/.." || exit 1

echo "=== Task 1: Hello ==="
rm -rf out
mkdir out
javac -encoding UTF-8 -d out tests/Check.java || exit 1

if ! java -cp out Check --started '\bmain\b|System' src/Hello.java; then
    echo "Nothing written yet in: src/Hello.java"
    echo
    echo "NOT STARTED"
    exit 1
fi

if ! ERRORS=$(javac -encoding UTF-8 -d out src/Hello.java 2>&1); then
    echo "[ ] compiles"
    echo "$ERRORS" | grep -m1 'error:' | sed 's/^/    /'
    echo
    echo "INCOMPLETE (does not compile)"
    exit 1
fi
echo "[x] compiles"

java -cp out Hello > out/output.txt 2>&1
java -cp out Check --compare out/output.txt "Hello, Java!"
